/* Scoped general chat approval. Server state and consent remain authoritative. */
(() => {
 const panel=document.createElement('details');panel.id='generalChatPanel';panel.className='general-chat';
 panel.innerHTML=`<summary id="generalChatHeading">일반 대화 전송 검토 · 시험</summary><p id="generalChatCapability" role="status"></p><p id="generalChatHelp">입력 준비는 전송하지 않습니다. 각 요청과 도구 결과의 전달은 따로 확인합니다. 실제 Claude 연결과 영상 생성은 지원하지 않습니다.</p>
 <form id="generalChatForm"><label for="generalChatPrompt">요청 초안</label><textarea id="generalChatPrompt" rows="4" maxlength="2000" required placeholder="음원에 맞는 장면을 제안해 주세요"></textarea>
 <div class="general-chat-limits"><label for="generalChatMaximum">한 회차 비용 상한 (USD)</label><input id="generalChatMaximum" type="number" min="0.000001" max="0.1" step="0.000001" value="0.01" required><label id="generalChatTotalLabel" for="generalChatTotal">전체 대화 비용 상한 (USD)</label><input id="generalChatTotal" type="number" min="0.000001" max="0.4" step="0.000001" value="0.04"></div>
 <button id="generalChatPrepare" type="submit">전송 내용 준비 · 전송 없음</button></form><p id="generalChatStatus" role="status" aria-live="polite"></p><div id="generalChatReviews" aria-label="전송 내용 검토"></div><div id="generalChatTurns" aria-label="대화 결과"></div><button type="button" id="generalChatRefresh">저장된 대화 상태 다시 확인</button>`;
 document.getElementById('modelChatPanel').after(panel);
 const el=id=>document.getElementById(id);let scope='',inFlight=false,renderedReviews='',renderedTurns='';
 const key=()=>conversationDraftKey('general-chat');
 const money=n=>'$'+(Number(n)/1000000).toFixed(6);
 const micro=value=>{if(!/^(?:\d+)(?:\.\d{1,6})?$/.test(value))return null;const [a,b='']=value.split('.');const n=Number(a)*1000000+Number((b+'000000').slice(0,6));return Number.isSafeInteger(n)?n:null};
 const allowed=cap=>cap?.available===true&&((cap.external_transmission===false&&['contract-fake','contract-live-test'].includes(cap.mode))||(cap.external_transmission===true&&cap.mode==='anthropic-live'));
 const bounded=mode=>['contract-live-test','anthropic-live'].includes(mode);
 const label=mode=>mode==='contract-fake'?'합성 응답 시험 · 외부 전송 없음':mode==='contract-live-test'?'로컬 시험 서버 · 실제 Claude 아님':mode==='anthropic-live'?'Claude 전송 설정됨':'사용 불가';
 const usageLabel=turn=>turn.usage_cost_usd==null||(turn.pricing_status!=='priced'&&turn.message_status!=='not_sent')?'사용량 기준 금액 미확인':'사용량 기준 금액 $'+turn.usage_cost_usd;
 function layout(live){if(panel.dataset.liveLayout===String(live))return;panel.dataset.liveLayout=String(live);const legacy=el('modelChatPanel');if(live){el('guidedBrief').before(panel);legacy.hidden=true;panel.open=true}else{legacy.after(panel);legacy.hidden=false}}
 const toolLabels={propose_media_plan:'장면 계획 제안',search_project_context:'프로젝트 내용 검색',propose_timeline_changes:'편집 변경 제안',request_render:'출력 요청',propose_motion_scene:'모션 구성 제안',request_motion_render:'승인된 모션 후보 렌더'};
 const states={queued:'대기 중',running:'처리 중',cancel_requested:'취소 요청 중',cancelled:'취소됨',completed:'답변 확인',awaiting_continuation_approval:'추가 전달 승인 대기',continuation_rejected:'추가 전달 거절됨',outcome_unknown:'결과 미확정 · 자동 재호출 없음',blocked_before_message:'전달 전 차단',response_validation_failed:'응답 확인 실패',limit_reached:'대화 한도에 도달'};
 function controls(){const p=project(),cap=p?.general_chat_connection;const blocked=!!busy||inFlight||!!pendingId()||!!pendingId.failed||!!dirty;const active=(p?.general_chat_turns||[]).some(t=>['queued','running','outcome_unknown','cancel_requested','awaiting_continuation_approval'].includes(t.status));el('generalChatPrepare').disabled=blocked||!allowed(cap)||active||(p?.general_chat_previews||[]).length>0;el('generalChatRefresh').disabled=!!busy||inFlight;panel.querySelectorAll('[data-general-decision],[data-general-cancel]').forEach(b=>b.disabled=blocked||!allowed(cap))}
 function refresh(){
  const next=key();if(next!==scope){scope=next;el('generalChatPrompt').value=draftRead(scope)||'';el('generalChatMaximum').value=draftRead(scope+'-maximum')??'0.01';el('generalChatTotal').value=draftRead(scope+'-total')??'0.04';el('generalChatStatus').textContent='';renderedReviews='';renderedTurns=''}
  const p=project(),cap=p?.general_chat_connection,enabled=allowed(cap);
  const actual=enabled&&cap.mode==='anthropic-live';layout(actual);el('generalChatHeading').textContent=actual?'모델과 계획·편집 상담':'일반 대화 전송 검토 · 시험';
  el('generalChatCapability').textContent=enabled?(actual?cap.reason||'연결 설정됨. 계정 접근과 청구는 아직 확인하지 않았습니다.':label(cap.mode)):'현재 일반 대화 연결이 없습니다. 요청 초안을 보관할 수 있으며, 실제 Claude 전송은 사용할 수 없습니다.';
  el('generalChatHelp').textContent=actual?'계획과 편집 변경안을 요청할 수 있습니다. 요청과 도구 결과를 전달하기 전에 내용과 비용 상한을 확인하며, 변경안 적용과 출력 승인은 별도입니다.':'입력 준비는 전송하지 않습니다. 각 요청과 도구 결과의 전달은 따로 확인합니다. 실제 Claude 연결과 영상 생성은 지원하지 않습니다.';
  const live=bounded(cap?.mode);el('generalChatTotalLabel').hidden=!live;el('generalChatTotal').hidden=!live;el('generalChatTotal').required=live;
  const reviews=p?.general_chat_previews||[],turns=p?.general_chat_turns||[];
  const reviewData=JSON.stringify(reviews);if(renderedReviews!==reviewData){
   const checked=new Set([...el('generalChatReviews').querySelectorAll('input:checked')].map(x=>x.dataset.rights));const opened=new Set([...el('generalChatReviews').querySelectorAll('details[open]')].map(x=>x.dataset.detail));
   const focused=document.activeElement?.dataset?.generalDecision||document.activeElement?.dataset?.rights;
   el('generalChatReviews').innerHTML=reviews.map(v=>`<article class="general-chat-card"><h3>${v.turn_id?'도구 결과 추가 전달 검토':'요청 전송 검토'}</h3><dl><dt>수신처</dt><dd>${esc(v.mode==='contract-fake'?'합성 시험 · 외부 전송 없음':v.destination)}</dd><dt>방식</dt><dd>${esc(label(v.mode))}</dd><dt>모델</dt><dd>${esc(v.binding?.model||'확인 필요')}</dd><dt>자료 범위</dt><dd>${esc(v.data_scope)}</dd><dt>한 회차 상한 / 최대 예약액</dt><dd>${money(v.maximum_micro)} / ${money(v.reserve_micro)}</dd><dt>전체 대화 상한</dt><dd>${v.total_maximum_micro==null?'합성 시험: 전체 상한 미적용':money(v.total_maximum_micro)}</dd><dt>도구 범위</dt><dd>${esc((v.tool_scope||[]).map(name=>toolLabels[name]||'확인 필요').join(', '))}</dd></dl><p>승인 후에도 서버에서 문맥과 예산을 다시 확인합니다. 자료 파일 자체는 전달하지 않습니다.</p><details data-detail="${esc(v.id)}" ${opened.has(v.id)?'open':''}><summary>전달할 전체 내용 보기 · 도구 결과 포함</summary><p>메시지 요청</p><pre>${esc(JSON.stringify(v.message_body,null,2))}</pre><p>토큰 수 확인 요청</p><pre>${esc(JSON.stringify(v.count_body,null,2))}</pre></details><label class="general-chat-rights"><input type="checkbox" data-rights="${esc(v.id)}" ${checked.has(v.id)?'checked':''}> 이 요청에 포함된 내용의 사용 및 전달 권한을 확인했습니다.</label><div class="general-chat-actions"><button type="button" data-general-decision="approve" data-preview="${esc(v.id)}">확인한 내용 승인</button><button type="button" data-general-decision="reject" data-preview="${esc(v.id)}">전달 거절</button></div></article>`).join('');
   renderedReviews=reviewData;if(focused)el('generalChatReviews').querySelector('[data-general-decision="'+focused+'"], [data-rights="'+focused+'"]')?.focus({preventScroll:true});
  }
  const turnData=JSON.stringify(turns);if(renderedTurns!==turnData){el('generalChatTurns').innerHTML=turns.map(t=>`<article class="general-chat-card"><h3>${esc(states[t.status]||'상태 확인 필요')}</h3><p>${esc(label(t.mode))} · ${esc(t.model||'')}</p><p class="general-chat-text">${esc(t.prompt||'')}</p>${t.answer?`<p class="general-chat-text">${esc(t.answer)}</p><p>${t.mode==='anthropic-live'?'모델 답변과 변경안의 적용·출력 승인은 별도입니다.':'시험 응답이며 제작 결과나 편집 승인이 아닙니다.'}</p>`:''}${t.error?`<p>${esc(t.error)}</p>`:''}<p>${esc(usageLabel(t))} · 청구 ${t.billing_confirmed?'확인':'미확인'}</p>${['queued','running','awaiting_continuation_approval'].includes(t.status)?`<button type="button" data-general-cancel="${esc(t.id)}">대화 작업 중단</button>`:''}</article>`).join('');renderedTurns=turnData}
  controls();
 }
 el('generalChatPrompt').addEventListener('input',()=>draftWrite(scope,el('generalChatPrompt').value));
 el('generalChatMaximum').addEventListener('input',()=>{if(scope)draftWrite(scope+'-maximum',el('generalChatMaximum').value)});
 el('generalChatTotal').addEventListener('input',()=>{if(scope)draftWrite(scope+'-total',el('generalChatTotal').value)});
 async function request(action,data){let outcome={status:'not_sent'};const current=scope;inFlight=true;controls();try{const ok=await act(action,data,undefined,value=>{outcome=value});if(current!==scope)return false;if(!ok){const messages={rejected:outcome.reason||'요청이 거절되었습니다. 입력을 확인하세요.',unknown:'요청 결과가 미확정입니다. 기존 요청 확인 후 계속하세요.',committed_refresh_failed:'저장됐지만 화면 갱신에 실패했습니다. 상태를 다시 확인하세요.',not_sent:'요청하지 못했습니다. 저장되지 않은 편집, 브라우저 저장소와 기존 요청을 확인하세요.'};el('generalChatStatus').textContent=messages[outcome.status]||'상태를 다시 확인하세요.'}return ok}finally{inFlight=false;refresh()}}
 el('generalChatForm').onsubmit=async e=>{e.preventDefault();if(!allowed(project()?.general_chat_connection)||inFlight||busy||scope!==key())return;const cap=project().general_chat_connection,maximum=micro(el('generalChatMaximum').value),total=micro(el('generalChatTotal').value);if(!maximum||maximum>100000||(bounded(cap.mode)&&(!total||total<maximum||total>400000))){el('generalChatStatus').textContent='비용 상한을 확인하세요.';return}const data={song:song(),prompt:el('generalChatPrompt').value,maximum_micro:maximum};if(bounded(cap.mode))data.total_maximum_micro=total;if(await request('general_chat_preview',data))el('generalChatStatus').textContent='전달할 내용을 준비했습니다. 확인하고 승인 또는 거절하세요. 아직 전달하지 않았습니다.'};
 el('generalChatReviews').onclick=async e=>{const b=e.target.closest('[data-general-decision]');if(!b||inFlight||busy||scope!==key()||!allowed(project()?.general_chat_connection))return;const v=(project()?.general_chat_previews||[]).find(x=>x.id===b.dataset.preview);if(!v)return;const rights=[...el('generalChatReviews').querySelectorAll('[data-rights]')].find(x=>x.dataset.rights===v.id)?.checked===true;const decision=b.dataset.generalDecision;if(decision==='approve'&&!rights){el('generalChatStatus').textContent='내용의 사용 및 전달 권한을 확인해 주세요.';return}if(decision==='approve'&&!v.turn_id&&v.message_body?.messages?.[0]?.content!==el('generalChatPrompt').value){el('generalChatStatus').textContent='초안이 바뀌었습니다. 이 검토를 거절하고 새 내용을 준비하세요.';return}if(await request('general_chat_decide',{song:song(),preview_id:v.id,manifest_sha256:v.manifest_sha256,decision,rights_confirmed:rights}))el('generalChatStatus').textContent=decision==='approve'?'승인을 저장했습니다. 대화 상태를 확인하세요.':'전달을 거절했습니다.'};
 el('generalChatTurns').onclick=async e=>{const b=e.target.closest('[data-general-cancel]');if(!b||busy||inFlight||scope!==key())return;if(await request('general_chat_cancel',{song:song(),turn:b.dataset.generalCancel}))el('generalChatStatus').textContent='중단 요청을 저장했습니다. 작업 상태를 확인하세요.'};
 el('generalChatRefresh').onclick=async()=>{if(dirty)return el('generalChatStatus').textContent='저장되지 않은 편집을 먼저 저장하세요. 초안은 유지됩니다.';try{await refreshState()}catch{el('generalChatStatus').textContent='상태를 불러오지 못했습니다. 초안은 유지됩니다.'}};
 panel.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const section=e.target.closest('details');if(section?.open){e.preventDefault();section.open=false;section.querySelector(':scope > summary')?.focus()}});
 async function refreshState(){await windowRefresh();refresh();el('generalChatStatus').textContent='저장된 대화 상태를 확인했습니다.'}
 const windowRefresh=()=>globalThis.LoretuneGeneralChatStateRefresh();
 window.LoretuneGeneralChat={refresh,syncControls:controls};
})();

